SELECT id, order_id, quantity, unit_price, CORR(unit_price, quantity) OVER (PARTITION BY product_id, order_id) AS corr_unit_price_quantity, FIRST_VALUE(unit_price, TRUE) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_unit_price, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC, id) AS seq_no, COUNT(unit_price) OVER (PARTITION BY product_id) AS product_id_count_unit_price FROM order_items;
